1	import { emit } from "@tauri-apps/api/event";
2	import { load } from "@tauri-apps/plugin-store";
3	import { Result } from "better-result";
4	import { createSignal } from "solid-js";
5	import type { Locale } from "../i18n";
6	import { type AppStyle, STYLE_LIST } from "./commands/apps";
7	import { listAudioDevices } from "./commands/audio";
8	import { saveBrowserValue, storageError } from "./errors";
9	import {
10		CURRENT_ONBOARDING_VERSION,
11		ONBOARDING_STEP_COUNT,
12		normalizeOnboardingStep,
13	} from "./onboarding";
14	import { DEFAULT_HOLD_TO_SPEAK_HOTKEY, DEFAULT_HOTKEY } from "./hotkeyUtils";
15	
16	export type Theme = "dark" | "light" | "system";
17	
18	export interface Settings {
19		theme: Theme;
20		hotkey: string;
21		holdToSpeakHotkey: string;
22		selectedMicrophoneId: string | null;
23		language: Locale;
24		muteMediaWhileRecording: boolean;
25		defaultStyle: AppStyle;
26		onboardingComplete: boolean;
27		onboardingStep: number;
28	}
29	
30	const DEFAULT_SETTINGS: Settings = {
31		theme: "system",
32		hotkey: DEFAULT_HOTKEY,
33		holdToSpeakHotkey: DEFAULT_HOLD_TO_SPEAK_HOTKEY,
34		selectedMicrophoneId: null,
35		language: "en",
36		muteMediaWhileRecording: false,
37		defaultStyle: "default",
38		onboardingComplete: false,
39		onboardingStep: 1,
40	};
41	
42	const STORE_NAME = "settings.json";
43	
44	let storeInstance: Awaited<ReturnType<typeof load>> | null = null;
45	
46	async function getStore() {
47		if (!storeInstance) {
48			storeInstance = await load(STORE_NAME, {
49				defaults: {
50					theme: DEFAULT_SETTINGS.theme,
51					hotkey: DEFAULT_SETTINGS.hotkey,
52					holdToSpeakHotkey: DEFAULT_SETTINGS.holdToSpeakHotkey,
53					selectedMicrophoneId: DEFAULT_SETTINGS.selectedMicrophoneId,
54					language: DEFAULT_SETTINGS.language,
55					muteMediaWhileRecording: DEFAULT_SETTINGS.muteMediaWhileRecording,
56					defaultStyle: DEFAULT_SETTINGS.defaultStyle,
57					onboardingComplete: DEFAULT_SETTINGS.onboardingComplete,
58					onboardingStep: DEFAULT_SETTINGS.onboardingStep,
59					onboardingVersion: CURRENT_ONBOARDING_VERSION,
60				},
61				autoSave: 500,
62			});
63		}
64		return storeInstance;
65	}
66	
67	export async function loadSettings(): Promise<Settings> {
68		const store = await getStore();
69		const theme = await store.get<Theme>("theme");
70		const hotkey = await store.get<string>("hotkey");
71		const holdToSpeakHotkey = await store.get<string>("holdToSpeakHotkey");
72		const selectedMicrophoneId = await store.get<string | null>("selectedMicrophoneId");
73		const language = await store.get<Locale>("language");
74		const muteMediaWhileRecording = await store.get<boolean>("muteMediaWhileRecording");
75		const storedDefaultStyle = await store.get<AppStyle>("defaultStyle");
76		const defaultStyle =
77			storedDefaultStyle && STYLE_LIST.includes(storedDefaultStyle)
78				? storedDefaultStyle
79				: DEFAULT_SETTINGS.defaultStyle;
80		const onboardingComplete = await store.get<boolean>("onboardingComplete");
81		const onboardingStep = await store.get<number>("onboardingStep");
82		const onboardingVersion = await store.get<number>("onboardingVersion");
83		const normalizedOnboardingStep = normalizeOnboardingStep(
84			onboardingStep ?? DEFAULT_SETTINGS.onboardingStep,
85			onboardingComplete ?? DEFAULT_SETTINGS.onboardingComplete,
86			onboardingVersion ?? 1
87		);
88	
89		if (normalizedOnboardingStep !== (onboardingStep ?? DEFAULT_SETTINGS.onboardingStep)) {
90			await store.set("onboardingStep", normalizedOnboardingStep);
91		}
92		if ((onboardingVersion ?? 1) !== CURRENT_ONBOARDING_VERSION) {
93			await store.set("onboardingVersion", CURRENT_ONBOARDING_VERSION);
94		}
95	
96		return {
97			theme: theme ?? DEFAULT_SETTINGS.theme,
98			hotkey: hotkey ?? DEFAULT_SETTINGS.hotkey,
99			holdToSpeakHotkey: holdToSpeakHotkey ?? DEFAULT_SETTINGS.holdToSpeakHotkey,
100			selectedMicrophoneId: selectedMicrophoneId ?? DEFAULT_SETTINGS.selectedMicrophoneId,
101			language: language ?? DEFAULT_SETTINGS.language,
102			muteMediaWhileRecording: muteMediaWhileRecording ?? DEFAULT_SETTINGS.muteMediaWhileRecording,
103			defaultStyle,
104			onboardingComplete: onboardingComplete ?? DEFAULT_SETTINGS.onboardingComplete,
105			onboardingStep: normalizedOnboardingStep,
106		};
107	}
108	
109	export async function saveTheme(theme: Theme): Promise<void> {
110		const store = await getStore();
111		await store.set("theme", theme);
112		saveBrowserValue("voxfusion-theme", theme);
113	}
114	
115	export async function saveHotkey(hotkey: string): Promise<void> {
116		const store = await getStore();
117		await store.set("hotkey", hotkey);
118	}
119	
120	export async function saveHoldToSpeakHotkey(hotkey: string): Promise<void> {
121		const store = await getStore();
122		await store.set("holdToSpeakHotkey", hotkey);
123	}
124	
125	export async function saveMicrophone(microphoneId: string | null): Promise<void> {
126		const store = await getStore();
127		await store.set("selectedMicrophoneId", microphoneId);
128	}
129	
130	export async function saveLanguage(language: Locale): Promise<void> {
131		const store = await getStore();
132		await store.set("language", language);
133	}
134	
135	export async function saveMuteMediaWhileRecording(enabled: boolean): Promise<void> {
136		const store = await getStore();
137		await store.set("muteMediaWhileRecording", enabled);
138	}
139	
140	export async function saveDefaultStyle(style: AppStyle): Promise<void> {
141		const store = await getStore();
142		await store.set("defaultStyle", style);
143	}
144	
145	export interface AudioDevice {
146		name: string;
147		isDefault: boolean;
148	}
149	
150	export async function getAudioInputDevices(): Promise<AudioDevice[]> {
151		const devices = await listAudioDevices();
152		if (Result.isError(devices)) return [];
153		return devices.value.map((device) => ({
154			name: device.name,
155			isDefault: device.is_default,
156		}));
157	}
158	
159	const [settings, setSettingsInternal] = createSignal<Settings>(DEFAULT_SETTINGS);
160	
161	export function useSettings() {
162		return settings;
163	}
164	
165	export async function initSettings(): Promise<void> {
166		const loaded = await loadSettings();
167		setSettingsInternal(loaded);
168		applyTheme(loaded.theme);
169		saveBrowserValue("voxfusion-theme", loaded.theme);
170	}
171	
172	export async function updateTheme(theme: Theme): Promise<void> {
173		await saveTheme(theme);
174		setSettingsInternal((prev) => ({ ...prev, theme }));
175		applyTheme(theme);
176		await emit("settings-changed");
177	}
178	
179	export async function updateHotkey(hotkey: string): Promise<void> {
180		await saveHotkey(hotkey);
181		setSettingsInternal((prev) => ({ ...prev, hotkey }));
182		await emit("settings-changed");
183	}
184	
185	export async function updateHoldToSpeakHotkey(hotkey: string): Promise<void> {
186		await saveHoldToSpeakHotkey(hotkey);
187		setSettingsInternal((prev) => ({ ...prev, holdToSpeakHotkey: hotkey }));
188		await emit("settings-changed");
189	}
190	
191	export async function updateMicrophone(microphoneId: string | null): Promise<void> {
192		await saveMicrophone(microphoneId);
193		setSettingsInternal((prev) => ({ ...prev, selectedMicrophoneId: microphoneId }));
194		await emit("settings-changed");
195	}
196	
197	export async function updateLanguage(
198		language: Locale,
199		setLocale: (locale: Locale) => void
200	): Promise<void> {
201		await saveLanguage(language);
202		setSettingsInternal((prev) => ({ ...prev, language }));
203		setLocale(language);
204	}
205	
206	export async function updateMuteMediaWhileRecording(enabled: boolean): Promise<void> {
207		await saveMuteMediaWhileRecording(enabled);
208		setSettingsInternal((prev) => ({ ...prev, muteMediaWhileRecording: enabled }));
209		await emit("settings-changed");
210	}
211	
212	export async function updateDefaultStyle(style: AppStyle): Promise<void> {
213		await saveDefaultStyle(style);
214		setSettingsInternal((prev) => ({ ...prev, defaultStyle: style }));
215		await emit("settings-changed");
216	}
217	
218	function applyTheme(theme: Theme): void {
219		const root = document.documentElement;
220	
221		if (theme === "system") {
222			const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
223			root.classList.toggle("dark", prefersDark);
224		} else {
225			root.classList.toggle("dark", theme === "dark");
226		}
227	}
228	
229	if (typeof window !== "undefined") {
230		window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => {
231			const currentSettings = settings();
232			if (currentSettings.theme === "system") {
233				applyTheme("system");
234			}
235		});
236	}
237	
238	export async function updateOnboardingStep(step: number): Promise<void> {
239		const store = await getStore();
240		await store.set("onboardingStep", step);
241		await store.save();
242		setSettingsInternal((prev) => ({ ...prev, onboardingStep: step }));
243	}
244	
245	export async function markOnboardingComplete(): Promise<void> {
246		setSettingsInternal((prev) => ({ ...prev, onboardingComplete: true, onboardingStep: 1 }));
247		const result = await Result.tryPromise({
248			try: async () => {
249				const store = await getStore();
250				await store.set("onboardingComplete", true);
251				await store.set("onboardingStep", 1);
252				await store.save();
253				await emit("settings-changed");
254			},
255			catch: (cause) => storageError("persist onboarding completion", cause),
256		});
257		if (Result.isError(result)) {
258			console.error("Failed to persist onboarding completion:", result.error);
259		}
260	}
261	
262	export async function resetOnboarding(): Promise<void> {
263		const store = await getStore();
264		await store.set("onboardingComplete", false);
265		setSettingsInternal((prev) => ({ ...prev, onboardingComplete: false }));
266	}
267	
268	export async function resumeOnboardingAt(step: number): Promise<void> {
269		const clamped = Math.min(Math.max(step, 1), ONBOARDING_STEP_COUNT);
270		setSettingsInternal((prev) => ({
271			...prev,
272			onboardingComplete: false,
273			onboardingStep: clamped,
274		}));
275		const result = await Result.tryPromise({
276			try: async () => {
277				const store = await getStore();
278				await store.set("onboardingComplete", false);
279				await store.set("onboardingStep", clamped);
280				await store.save();
281				await emit("settings-changed");
282			},
283			catch: (cause) => storageError("persist onboarding resume", cause),
284		});
285		if (Result.isError(result)) {
286			console.error("Failed to persist onboarding resume:", result.error);
287		}
288	}
