1	import { useNavigate } from "@solidjs/router";
2	import { getVersion } from "@tauri-apps/api/app";
3	import { listen } from "@tauri-apps/api/event";
4	import { getCurrentWindow } from "@tauri-apps/api/window";
5	import { Result } from "better-result";
6	import { type ParentProps, Show, createSignal, onCleanup, onMount } from "solid-js";
7	import appIcon from "../src-tauri/icons/icon.svg";
8	import Sidebar from "./components/Navigation";
9	import SettingsModal from "./components/SettingsModal";
10	import OnboardingWizard from "./components/onboarding/OnboardingWizard";
11	import { listInstalledApps } from "./lib/commands/apps";
12	import { listSiteDictionaries } from "./lib/commands/dictionary";
13	import { checkModelStatus } from "./lib/commands/model";
14	import { errorFields, logDiagnostic } from "./lib/diagnostics";
15	import { preloadFavicons } from "./lib/favicons";
16	import { MODEL_DOWNLOAD_STEP } from "./lib/onboarding";
17	import { capture } from "./lib/posthog";
18	import {
19		initSettings,
20		markOnboardingComplete,
21		resumeOnboardingAt,
22		updateMicrophone,
23		useSettings,
24	} from "./lib/settingsStore";
25	
26	const FORCE_SHOW_ONBOARDING =
27		import.meta.env.DEV && import.meta.env.VITE_FORCE_ONBOARDING === "true";
28	
29	type TauriWindow = Window & {
30		__TAURI_INTERNALS__?: unknown;
31	};
32	
33	function waitForTauriIPC(): Promise<void> {
34		if ((window as TauriWindow).__TAURI_INTERNALS__) return Promise.resolve();
35	
36		return new Promise((resolve, reject) => {
37			const timeout = setTimeout(() => {
38				clearInterval(interval);
39				reject(new Error("Tauri IPC bridge not ready after 5s"));
40			}, 5000);
41	
42			const interval = setInterval(() => {
43				if ((window as TauriWindow).__TAURI_INTERNALS__) {
44					clearInterval(interval);
45					clearTimeout(timeout);
46					resolve();
47				}
48			}, 50);
49		});
50	}
51	
52	function App(props: ParentProps) {
53		const settings = useSettings();
54		const navigate = useNavigate();
55		const [isSettingsOpen, setIsSettingsOpen] = createSignal(false);
56		const [isReady, setIsReady] = createSignal(false);
57	
58		const shouldShowOnboarding = () => {
59			if (FORCE_SHOW_ONBOARDING) return true;
60			return !settings().onboardingComplete;
61		};
62	
63		onMount(async () => {
64			// Cleanups are collected into one synchronously-registered onCleanup:
65			// onCleanup calls after an `await` run outside the reactive owner and
66			// would silently never fire (see UpdateNotification for the pattern).
67			let disposed = false;
68			const disposers: (() => void)[] = [];
69			onCleanup(() => {
70				disposed = true;
71				for (const dispose of disposers) dispose();
72			});
73			const addDisposer = (dispose: () => void) => {
74				if (disposed) {
75					dispose();
76				} else {
77					disposers.push(dispose);
78				}
79			};
80	
81			const handleWindowError = (event: ErrorEvent) => {
82				logDiagnostic("error", "app", "window_error", {
83					message: event.message,
84					source: event.filename,
85					line: event.lineno,
86					column: event.colno,
87					error: errorFields(event.error),
88				});
89			};
90			const handleUnhandledRejection = (event: PromiseRejectionEvent) => {
91				logDiagnostic("error", "app", "unhandled_rejection", {
92					reason: errorFields(event.reason),
93				});
94			};
95			window.addEventListener("error", handleWindowError);
96			window.addEventListener("unhandledrejection", handleUnhandledRejection);
97			addDisposer(() => {
98				window.removeEventListener("error", handleWindowError);
99				window.removeEventListener("unhandledrejection", handleUnhandledRejection);
100			});
101	
102			try {
103				logDiagnostic("info", "app", "mount_started");
104				capture("app_opened");
105				await waitForTauriIPC();
106	
107				const appVersion = await Result.tryPromise(() => getVersion());
108				logDiagnostic("info", "app", "ipc_ready", {
109					version: Result.isOk(appVersion) ? appVersion.value : null,
110				});
111	
112				await initSettings();
113				logDiagnostic("info", "app", "settings_initialized", {
114					onboardingComplete: settings().onboardingComplete,
115					onboardingStep: settings().onboardingStep,
116					defaultStyle: settings().defaultStyle,
117				});
118	
119				const modelReady = await checkModelStatus();
120				if (Result.isOk(modelReady) && !modelReady.value && settings().onboardingComplete) {
121					logDiagnostic("warn", "app", "model_missing_resume_onboarding");
122					await resumeOnboardingAt(MODEL_DOWNLOAD_STEP);
123				}
124				if (Result.isError(modelReady)) {
125					logDiagnostic("error", "app", "model_status_failed", errorFields(modelReady.error));
126					console.error("Failed to verify Whisper model state:", modelReady.error);
127				}
128	
129				setIsReady(true);
130				logDiagnostic("info", "app", "ready");
131	
132				void listSiteDictionaries().then((result) => {
133					if (Result.isOk(result)) {
134						logDiagnostic("debug", "app", "site_dictionaries_loaded", {
135							count: result.value.length,
136						});
137						preloadFavicons(result.value.map((g) => g.domain));
138					} else {
139						logDiagnostic("error", "app", "site_dictionaries_failed", errorFields(result.error));
140					}
141				});
142	
143				void listInstalledApps().then((result) => {
144					if (Result.isOk(result)) {
145						logDiagnostic("debug", "app", "installed_apps_loaded", {
146							count: result.value.length,
147						});
148					} else {
149						logDiagnostic("error", "app", "installed_apps_failed", errorFields(result.error));
150					}
151				});
152	
153				addDisposer(
154					await listen<string>("navigate", (event) => {
155						logDiagnostic("debug", "app", "navigate_event", { path: event.payload });
156						navigate(event.payload);
157					})
158				);
159	
160				addDisposer(
161					await listen<string>("select-microphone", async (event) => {
162						const deviceName = event.payload;
163						logDiagnostic("debug", "app", "select_microphone_event", {
164							hasDeviceName: Boolean(deviceName),
165						});
166						await updateMicrophone(deviceName || null);
167					})
168				);
169	
170				addDisposer(
171					await listen("accessibility-permission-needed", async () => {
172						logDiagnostic("warn", "app", "accessibility_permission_needed");
173						setIsSettingsOpen(true);
174						// The event is emitted from the overlay window while the main
175						// window may be hidden in the tray — surface it.
176						const mainWindow = getCurrentWindow();
177						await Result.tryPromise(async () => {
178							await mainWindow.show();
179							await mainWindow.setFocus();
180						});
181					})
182				);
183	
184				const handleKeyDown = (e: KeyboardEvent) => {
185					if (e.metaKey && e.key === ",") {
186						e.preventDefault();
187						logDiagnostic("debug", "app", "settings_shortcut_pressed");
188						setIsSettingsOpen(true);
189					}
190				};
191				window.addEventListener("keydown", handleKeyDown);
192				addDisposer(() => window.removeEventListener("keydown", handleKeyDown));
193			} catch (error) {
194				logDiagnostic("error", "app", "mount_failed", errorFields(error));
195				throw error;
196			}
197		});
198	
199		return (
200			<div class="relative min-h-screen h-full w-full bg-th-base transition-colors">
201				<div
202					class="pointer-events-none absolute inset-0 z-0"
203					style={{
204						"background-image":
205							"linear-gradient(var(--color-grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--color-grid-line) 1px, transparent 1px)",
206						"background-size": "40px 40px",
207					}}
208				/>
209				<div class="absolute top-0 left-0 right-0 h-6 z-50" data-tauri-drag-region />
210				<Show when={!isReady()}>
211					<div class="h-full flex flex-col items-center justify-center">
212						<img src={appIcon} alt="VoxFusion" class="w-16 h-16 mb-8" />
213						<div class="w-48 h-1 bg-border overflow-hidden">
214							<div class="w-1/4 h-full bg-ac animate-slide" />
215						</div>
216					</div>
217				</Show>
218				<Show when={isReady()}>
219					<Show
220						when={!shouldShowOnboarding()}
221						fallback={
222							<OnboardingWizard
223								initialStep={settings().onboardingStep}
224								onComplete={() => {
225									capture("onboarding_completed");
226									markOnboardingComplete();
227								}}
228							/>
229						}
230					>
231						<div class="flex h-full">
232							<Sidebar onOpenSettings={() => setIsSettingsOpen(true)} />
233							<main class="flex-1 overflow-auto pt-6">{props.children}</main>
234						</div>
235						<SettingsModal isOpen={isSettingsOpen()} onClose={() => setIsSettingsOpen(false)} />
236					</Show>
237				</Show>
238			</div>
239		);
240	}
241	
242	export default App;
243

