			>
				<div
					class={`w-full transition-all duration-200 ${
						isAnimating()
							? animationDirection() === "forward"
								? "opacity-0 translate-x-8"
								: "opacity-0 -translate-x-8"
							: "opacity-100 translate-x-0"
					}`}
				>
					<Show when={currentStep() === 1}>
						<MicrophonePermissionStep onPermissionChange={setMicPermissionGranted} />
					</Show>
					<Show when={currentStep() === 2}>
						<AccessibilityPermissionStep onPermissionChange={setAccessibilityPermissionGranted} />
					</Show>
					<Show when={currentStep() === 3}>
						<MicrophoneStep />
					</Show>
					<Show when={currentStep() === 4}>
						<HotkeyStep />
					</Show>
					<Show when={currentStep() === 5}>
						<ModelDownloadStep onDownloadComplete={() => setModelDownloaded(true)} />
					</Show>
					<Show when={currentStep() === 6}>
						<LearningStep onTranscriptionComplete={() => setLearningCompleted(true)} />
					</Show>
					<Show when={currentStep() === 7}>
						<CompletionStep />
					</Show>
				</div>
			</div>

			<div
				class={`flex items-center justify-between w-full mt-8 transition-all duration-300 ${currentStep() === 6 ? "max-w-4xl" : "max-w-2xl"}`}
			>
				<Show when={currentStep() > 1} fallback={<div />}>
					<button
						type="button"
						onClick={goToPrevious}
						class="px-6 py-3 font-mono text-txt-secondary hover:text-txt-primary transition-colors uppercase tracking-wider text-sm border border-border-strong hover:border-ac"
					>
						{t("onboarding.back")}
					</button>
				</Show>

				<Show
					when={currentStep() < ONBOARDING_STEP_COUNT}
					fallback={
						<button
							type="button"
							onClick={handleComplete}
							class="px-8 py-3 bg-ac text-ac-on font-mono font-bold uppercase tracking-wider text-sm hover:bg-ac-hover transition-colors"
						>
							{t("onboarding.getStarted")}
						</button>
					}
				>
					<button
						type="button"
						onClick={goToNext}
						disabled={!canProceed()}
						class="px-8 py-3 bg-ac text-ac-on font-mono font-bold uppercase tracking-wider text-sm hover:bg-ac-hover transition-colors disabled:opacity-30"
					>
						{t("onboarding.next")}
					</button>
				</Show>
			</div>
		</div>
	);
}

